style.css:
@-moz-document domain("eva.fing.edu.uy") {
body, #page, #region-main, .card, .modal-content {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    
    header, .navbar, .navbar-inner, .primary-navigation {
        background-color: #1f1f1f !important;
        color: #ffffff !important;
    }

    
    a, .aalink {
        color: #80cbc4 !important;
    }
    a:hover, .aalink:hover {
        color: #4db6ac !important;
        text-decoration: underline;
    }

    
    #block-region-side-pre, #block-region-side-post, .block {
        background-color: #1e1e1e !important;
        border: 1px solid #333 !important;
    }

    
    table, th, td {
        background-color: #1a1a1a !important;
        border-color: #333 !important;
        color: #e0e0e0 !important;
    }

    
    .btn, 
    .btn-primary, 
    .btn-secondary, 
    .btn-outline-secondary, 
    .btn-outline-primary {
        background-color: #2c2c2c !important;
        color: #e0e0e0 !important;
        border: 1px solid #444 !important;
    }
    .btn:hover, 
    .btn-primary:hover, 
    .btn-secondary:hover, 
    .btn-outline-secondary:hover, 
    .btn-outline-primary:hover {
        background-color: #3d3d3d !important;
        border-color: #666 !important;
        color: #ffffff !important;
    }

    
    input, select, textarea {
        background-color: #1f1f1f !important;
        color: #ffffff !important;
        border: 1px solid #444 !important;
    }

    
    .alert, .notification, .message {
        background-color: #262626 !important;
        border: 1px solid #444 !important;
        color: #e0e0e0 !important;
    }

    
    [class*="icon"] {
        filter: invert(80%) hue-rotate(180deg);
    }

    
    hr, 
    .card, 
    .block, 
    .activity, 
    .activityinstance, 
    .content, 
    .table, 
    .generaltable, 
    .box,
    .course-content,
    .section,
    .block .header,
    .block .title {
        border-color: #333 !important;
        background-color: #1a1a1a !important;
    }

    
    .nav-tabs .nav-link,
    .nav-tabs .nav-link.active {
        background-color: #1a1a1a !important;
        border: 1px solid #333 !important;
        color: #e0e0e0 !important;
    }

    
    #page, 
    #region-main,
    #region-main-box {
        border: none !important;
        background-color: #121212 !important;
    }

@-moz-document domain("eva.fing.edu.uy") {
    
    .card, 
    .card-body,
    .card-block,
    .card-header,
    .course-content,
    .section,
    .activity,
    .activityinstance,
    .box,
    .generalbox,
    #region-main,
    #region-main-box,
    #page-content {
        border: none !important;
        box-shadow: none !important;
    }

    
    .card, 
    .card-body,
    .card-block,
    .card-header,
    .course-content,
    .section,
    .box,
    .generalbox {
        background-color: #1a1a1a !important;
    }
}
}
